export function getIndicatorScenario(eventName: string, country?: string): IndicatorScenarioItem {
    if (country && INDICATOR_SCENARIOS_DATABASE[country + " | " + eventName]) {
        return INDICATOR_SCENARIOS_DATABASE[country + " | " + eventName];
    }
    for (const [key, val] of Object.entries(INDICATOR_SCENARIOS_DATABASE)) {
        if (key.endsWith(" | " + eventName) || key.toLowerCase().includes(eventName.toLowerCase())) {
            return val;
        }
    }
    // Fallback varsayılan senaryo
    return {
        above: "Açıklanan verinin beklentilerin üzerinde gelmesi, ekonomide ilgili gösterge yönünde beklenenden daha kuvvetli bir hareket olduğunu ortaya koyar. Büyük kararlarını ve harcama planlarını gözden geçirmek durumunda kalsan da {userName}, piyasadaki bu sürpriz hareketlilik yeni yatırım fırsatlarını da beraberinde getirebilir. Şirketler ve finansal kurumlar pozisyonlarını bu yeni dengeye göre güncellerken, kısa vadede varlık fiyatlarında dalgalanmalar yaşanabilir. Bu durum, piyasa dengelerinin yeniden kurulduğu temkinli bir geçiş sürecini başlatır.",
        parallel: "Açıklanan verinin tam olarak ekonomistlerin tahmin ettiği düzeyde gerçekleşmesi, piyasalardaki belirsizliği ortadan kaldırarak güven tazeler. Kararın önceden öngörülüp fiyatlanmış olması sayesinde {userName}, ne döviz kurlarında ne de borsa tarafında ani ve yıkıcı bir fırtınayla karşılaşmazsın. İşletmeler ve tüketiciler önlerini net gördükleri için planlı ticaretlerini ve bütçe dengelerini sakin bir kararlılıkla sürdürür. Bu senaryo piyasaya ekstra bir coşku getirmese de, finansal istikrarın korunduğunu teyit eder.",
        below: "Verinin beklentilerin belirgin biçimde altında kalması, ekonomide beklenen ivmenin zayıfladığına ve para politikasında gevşeme alanının açıldığına işaret eder. Borçlanma ve kredi maliyetlerinin düşeceği beklentisiyle birlikte {userName}, uzun zamandır ertelediğin harcamaları veya varlık yatırımlarını yeniden değerlendirmek senin için cazip hale gelebilir. Piyasaya giren sıcak para beklentisi hisse senetlerinde ve emtialarda canlılık yaratır. Ancak talepteki erken hareketlenme, orta vadede fiyat dengelerinin yeniden bozulması riskini taşır."
    };
}
